  1	interface Env {
  2	  ASSETS: Fetcher;
  3	  GOOGLE_MAPS_API_KEY: string;
  4	}
  5	
  6	type Coordinates = { lat: number; lng: number };
  7	
  8	function json(body: unknown, status = 200, cacheControl = 'public, max-age=86400') {
  9	  return new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json; charset=UTF-8', 'cache-control': cacheControl } });
 10	}
 11	
 12	function endpointFromDescription(description: string) {
 13	  const match = description.match(/\b(?:to|into|down to|up to)\s+(.+?)(?:[.;]|$)/i);
 14	  if (!match) return null;
 15	  const endpoint = match[1].replace(/\b(?:near|at)\s+the\s+end\s+of\s+the\s+stairs?\b/ig, '').replace(/\s+/g, ' ').trim();
 16	  return endpoint.length >= 3 ? `${endpoint}, San Francisco, CA` : null;
 17	}
 18	
 19	async function geocode(address: string, key: string): Promise<{ point: Coordinates; label: string } | null> {
 20	  const url = new URL('https://maps.googleapis.com/maps/api/geocode/json');
 21	  url.searchParams.set('address', address);
 22	  url.searchParams.set('components', 'locality:San Francisco|administrative_area:CA|country:US');
 23	  url.searchParams.set('key', key);
 24	  const response = await fetch(url);
 25	  const payload = await response.json() as { status: string; error_message?: string; results?: { formatted_address: string; geometry: { location: Coordinates } }[] };
 26	  if (payload.status === 'ZERO_RESULTS') return null;
 27	  if (payload.status !== 'OK' || !payload.results?.[0]) {
 28	    if (payload.error_message?.includes('not activated')) throw new Error('Enable the Google Geocoding API for this key, then try again.');
 29	    throw new Error(payload.error_message || 'Google could not geocode this stairway description.');
 30	  }
 31	  return { point: payload.results[0].geometry.location, label: payload.results[0].formatted_address };
 32	}
 33	
 34	async function elevationPath(origin: Coordinates, destination: Coordinates, key: string) {
 35	  const url = new URL('https://maps.googleapis.com/maps/api/elevation/json');
 36	  url.searchParams.set('path', `${origin.lat},${origin.lng}|${destination.lat},${destination.lng}`);
 37	  url.searchParams.set('samples', '24');
 38	  url.searchParams.set('key', key);
 39	  const response = await fetch(url);
 40	  const payload = await response.json() as { status: string; error_message?: string; results?: { elevation: number }[] };
 41	  if (payload.status !== 'OK' || !payload.results?.length) {
 42	    if (payload.error_message?.includes('not activated')) throw new Error('Enable the Google Elevation API for this key, then try again.');
 43	    throw new Error(payload.error_message || 'Google could not calculate elevation for this stairway.');
 44	  }
 45	  const elevations = payload.results.map(result => result.elevation);
 46	  const uphillMeters = elevations.slice(1).reduce((total, elevation, index) => total + Math.max(0, elevation - elevations[index]), 0);
 47	  const downhillMeters = elevations.slice(1).reduce((total, elevation, index) => total + Math.max(0, elevations[index] - elevation), 0);
 48	  return {
 49	    gainFeet: Math.round(uphillMeters * 3.28084),
 50	    descentFeet: Math.round(downhillMeters * 3.28084),
 51	    verticalFeet: Math.round((uphillMeters + downhillMeters) * 3.28084),
 52	    startFeet: Math.round(elevations[0] * 3.28084),
 53	    endFeet: Math.round(elevations.at(-1)! * 3.28084)
 54	  };
 55	}
 56	
 57	function nearbyPoints(center: Coordinates) {
 58	  const latitudeMeters = 1 / 111195;
 59	  const longitudeMeters = 1 / (111195 * Math.cos(center.lat * Math.PI / 180));
 60	  return [0, 45, 90, 135, 180, 225, 270, 315].map(degrees => {
 61	    const radians = degrees * Math.PI / 180;
 62	    return { lat: center.lat + Math.cos(radians) * 45 * latitudeMeters, lng: center.lng + Math.sin(radians) * 45 * longitudeMeters };
 63	  });
 64	}
 65	
 66	async function localElevationRange(center: Coordinates, key: string) {
 67	  const url = new URL('https://maps.googleapis.com/maps/api/elevation/json');
 68	  url.searchParams.set('locations', [...nearbyPoints(center), center].map(point => `${point.lat},${point.lng}`).join('|'));
 69	  url.searchParams.set('key', key);
 70	  const response = await fetch(url);
 71	  const payload = await response.json() as { status: string; error_message?: string; results?: { elevation: number }[] };
 72	  if (payload.status !== 'OK' || !payload.results?.length) throw new Error(payload.error_message || 'Google could not calculate local elevation for this stairway.');
 73	  const elevations = payload.results.map(result => result.elevation);
 74	  return {
 75	    gainFeet: Math.round((Math.max(...elevations) - Math.min(...elevations)) * 3.28084),
 76	    startFeet: Math.round(elevations.at(-1)! * 3.28084),
 77	    endFeet: Math.round(Math.max(...elevations) * 3.28084)
 78	  };
 79	}
 80	
 81	function estimatedSteps(verticalFeet: number) {
 82	  return Math.max(1, Math.round(verticalFeet * 12 / 7));
 83	}
 84	
 85	async function estimateElevation(request: Request, env: Env, ctx: ExecutionContext) {
 86	  const url = new URL(request.url);
 87	  const lat = Number(url.searchParams.get('lat'));
 88	  const lng = Number(url.searchParams.get('lng'));
 89	  const description = url.searchParams.get('description') || '';
 90	  if (!Number.isFinite(lat) || !Number.isFinite(lng) || description.length > 500) return json({ error: 'A mapped stairway description is required.' }, 400, 'no-store');
 91	  const inferredAddress = endpointFromDescription(description);
 92	  const cache = caches.default;
 93	  const cached = await cache.match(request);
 94	  if (cached) return cached;
 95	  try {
 96	    if (inferredAddress) {
