     1	export type Assessable = { name: string; rating: number; steps: string };
     2	export type Tier = 'Monitor' | 'Recommended' | 'Priority Candidate' | 'Immediate Escalation Advised';
     3	export type Assessment = { score: number; steps: number; provisional: boolean; glideSeconds: number; glide: string; tier: Tier; candidate: boolean; remark: string };
     4	export const tiers: Tier[] = ['Monitor', 'Recommended', 'Priority Candidate', 'Immediate Escalation Advised'];
     5	const secondsPerStep = .25;
     6	export const tierFor = (score: number): Tier => score < 32 ? 'Immediate Escalation Advised' : score < 45 ? 'Priority Candidate' : score < 65 ? 'Recommended' : 'Monitor';
     7	export const isScenic = (stair: Assessable) => /\b(views?|panoram\w*|overlook|lookout)\b/i.test(stair.name);
     8	export function assessStairway(stair: Assessable): Assessment {
     9	  const parsed = parseInt(stair.steps, 10);
    10	  const provisional = !(parsed > 0);
    11	  const steps = provisional ? 28 + stair.rating * 14 : parsed;
    12	  const score = Math.max(0, Math.min(100, Math.round(100 - stair.rating * 9 - steps * .21)));
    13	  const glideSeconds = Math.round(steps * secondsPerStep);
    14	  const tier = tierFor(score);
    15	  return { score, steps, provisional, glideSeconds, glide: `${glideSeconds} seconds of effortless glide.`, tier, candidate: tier === 'Priority Candidate' || tier === 'Immediate Escalation Advised', remark: remarkFor(stair, steps, provisional, tier) };
    16	}
    17	function remarkFor(stair: Assessable, steps: number, provisional: boolean, tier: Tier) {
    18	  const long = steps >= 100, rated = stair.rating >= 4, scenic = isScenic(stair);
    19	  const parts: string[] = [];
    20	  parts.push({
    21	    'Immediate Escalation Advised': 'This climb costs walkers more time than almost anything else in the city.',
    22	    'Priority Candidate': 'This one asks a lot of anyone carrying groceries.',
    23	    'Recommended': 'A moving staircase would save a few honest minutes here.',
    24	    'Monitor': 'Most people take this one in stride.'
    25	  }[tier]);
    26	  if (provisional) parts.push(`Nobody has counted the steps here, so we estimated ${steps} from the rating.`);
    27	  else if (long) parts.push(`${steps} steps is ${steps} separate chances to stop and reconsider.`);
    28	  else parts.push(`${steps} steps, every one of them under your own power.`);
    29	  if (scenic) parts.push('People come here for the view, which sadly does nothing for travel time.');
    30	  if (rated) parts.push(`A ${stair.rating}-star rating means a lot of people make this climb.`);
    31	  else if (stair.rating === 0) parts.push('The rating is unconfirmed, so we assumed ordinary foot traffic.');
    32	  parts.push({
    33	    'Immediate Escalation Advised': 'Recommend immediate escalation.',
    34	    'Priority Candidate': 'Worth penciling into the next budget.',
    35	    'Recommended': 'Worth another look down the road.',
    36	    'Monitor': 'No action needed. We’ll keep an eye on it.'
    37	  }[tier]);
    38	  return parts.join(' ');
    39	}

